data: {"index":1,"delta":{"text":", and preparing it for translation. It is highly dependent on the source programming language.\n\n#### 1. Lexical Analysis (Scanning)\n","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":"The compilation process begins with the **lexer** (or scanner). The lexer reads the raw source code as a stream of characters","type":"text"},"event_type":"step.delta"}

